  ui_story_30120601_45_dialog_content = "Me parece recordar que no vestían el uniforme de Illumina, pero parecían llevar una falda larga...",
  ui_story_30120601_46_dialog_content = "Sin embargo, mis garras tenían algo de cabello rubio. Sigo preguntándome si soñé con Yumi...",
  ui_story_30120601_47_dialog_content = "Ah, necesito volver al trabajo ahora. No más dormir en el trabajo para mí, ¡miau!",
  ui_story_30120601_48_dialog_content = "¿Parece que a Punisher le gusta sorprender a los que tienen cola?",
