  ui_story_30120601_51_dialog_content = "¡Ay! ¡¿Qué es tan caliente?!",
  ui_story_30120601_52_dialog_content = "¡¿Te llamó la atención ahora, eh?! ¡Dale una cálida bienvenida a Punisher!",
