  ui_story_30120601_66_option_content = "¡Vamos! ¡Llévaselo a ella!",
  ui_story_30120601_67_dialog_content = "♪ Piensa que tus nuevos y elegantes hilos pueden engañar a todos nuestros ojos ♪",
  ui_story_30120601_68_dialog_content = "♪ Escóndete en las sombras, pero tonto, soy un Caelestita, no te sorprendas tanto ♪",
