  ui_story_30120601_70_dialog_content = "¡Eres Némesis, también conocido como el ejecutor de la justicia!",
  ui_story_30120601_71_dialog_content = "¿Por qué haces todo esto para engañar a la gente?",
  ui_story_30120601_72_dialog_content = "Pff, es posible que me hayas desenmascarado, pero aún así...",
  ui_story_30120601_73_dialog_content = "¡Es mi turno!",
