  ui_story_30120601_77_dialog_content = "♪ Hoy traigo una advertencia, y es mejor que creas en la partitura, no dejaré que retuerzas los corazones de las personas nunca más ♪",
  ui_story_30120601_78_dialog_content = "Tú... Yo no soy así... Yo no...",
  ui_story_30120601_79_dialog_content = "Argh...",
