  ui_story_30120601_81_dialog_content = "Eh...? ¿Qué estás haciendo aquí?",
  ui_story_30120601_82_dialog_content = "Vine cuando tenía un minuto libre, solo para encontrarte inconsciente.",
  ui_story_30120601_83_dialog_content = "No sé qué acaba de pasar, pero de repente me sentí extrañamente arrepentido y me desmayé...",
