  ui_story_30120601_85_dialog_content = "¿También conociste a Punisher? ¿La miraste bien?",
  ui_story_30120601_86_dialog_content = "¡Yo se quien es ella! ella es...",
  ui_story_30120601_87_dialog_content = "Nemesis!",
  ui_story_30120601_88_dialog_content = "¿Qué? ¿En serio? ¿Pero Punisher no está en uniforme?",
  ui_story_30120601_89_dialog_content = "¡Ajaja! Creo que PlayerName debe haber estado tan profundamente dormido como yo, ¡miau!",
  ui_story_30120601_90_dialog_content = "¿Este niño está soñando? Bueno lo que sea. Tengo cosas que hacer, así que nos vemos luego.",
  ui_story_30120601_91_dialog_content = "¿Has estado exagerando? ¿Por qué no regresas a tu habitación y descansas bien? Voy a ponerme a trabajar ahora.",
