  ui_story_30120601_93_dialog_content = "♪ ¿No puedes distinguir lo que es real de lo que no lo es? La cabeza de Caelestite todavía está en el cielo ♪",
  ui_story_30120601_94_dialog_content = "♪ Mejor despierta a la realidad, cuando mucho de lo que dices que harás resulta ser mentira ♪",
  ui_story_30120601_95_dialog_content = "¡Sabía que no lo soñé! ¡Es ella!",
